        // The break statements prevent the day case from falling through
        // into the night case (which would run nightAct on every day step).
        this.phase = phase;
        switch (phase) {
            case DAY:
                dayAct(newActors);
                break;
            case NIGHT:
                nightAct(newActors);
                break;
        }
    }

