import java.util.*;

/** Verifies default-schedule behavior preservation AND strategy swappability. */
public class StrategyProbe {
    static class T extends Actor {
        String ran = "";
        T(Field f, Location l){ super(f, l); }
        protected void dayAct(List<Actor> n){ ran = "day"; }
        protected void nightAct(List<Actor> n){ ran = "night"; }
        protected double getFoodValue(){ return 0; }
        protected void setWeatherEffects(){ }
    }
    static String runStep(T t, int step){
        t.act(new ArrayList<>(), Phase.forStep(step), Weather.SUNNY);
        return t.ran;
    }

    public static void main(String[] a){
        boolean ok = true;

        // 1) Default schedule == original dispatch (even->day, odd->night)
        for (int step = 0; step <= 3; step++) {
            T t = new T(new Field(1,1), new Location(0,0));
            String r = runStep(t, step);
            boolean expectDay = step % 2 == 0;
            ok &= r.equals(expectDay ? "day" : "night");
        }
        System.out.println("default schedule preserves behavior: " + ok);

        // 2) Swap day/night via strategy, WITHOUT touching Actor.act
        T s = new T(new Field(1,1), new Location(0,0));
        s.setSchedule(s.getSchedule().swapped(Phase.DAY, Phase.NIGHT));
        String dayStep = runStep(s, 0);   // step 0 = DAY phase, but swapped -> nightAct
        String nightStep = runStep(s, 1); // step 1 = NIGHT phase, but swapped -> dayAct
        boolean swapOk = dayStep.equals("night") && nightStep.equals("day");
        System.out.println("swapped schedule: DAY->"+dayStep+", NIGHT->"+nightStep+"  OK="+swapOk);

        // 3) Inject a fully custom strategy
        T c = new T(new Field(1,1), new Location(0,0));
        final List<String> log = new ArrayList<>();
        c.setSchedule(new Schedule()
            .on(Phase.DAY,   n -> log.add("custom-day"))
            .on(Phase.NIGHT, n -> log.add("custom-night")));
        runStep(c, 0); runStep(c, 1);
        boolean customOk = log.equals(List.of("custom-day", "custom-night"));
        System.out.println("custom strategy log=" + log + "  OK=" + customOk);

        System.out.println("ALL_OK=" + (ok && swapOk && customOk));
    }
}
